#!/usr/bin/env python3
"""
Script to reproduce the Azure B2C client_id in scopes issue.
"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'msal'))

from msal import PublicClientApplication
from msal.authority import Authority
from tests.http_client import MinimalHttpClient
import json


def test_regular_azure_ad():
    """Test regular Azure AD behavior - should work as before"""
    print("Testing regular Azure AD behavior...")

    # Regular Azure AD authority - mock the HTTP client to avoid network calls
    authority_url = "https://login.microsoftonline.com/common"
    client_id = "test-client-id"

    # Mock HTTP client that returns fake OpenID configuration
    class MockHttpClient:
        def get(self, url, **kwargs):
            return type('Response', (), {
                'status_code': 200,
                'text': json.dumps({
                    'authorization_endpoint': 'https://login.microsoftonline.com/common/oauth2/v2.0/authorize',
                    'token_endpoint': 'https://login.microsoftonline.com/common/oauth2/v2.0/token'
                })
            })()

    app = PublicClientApplication(
        client_id=client_id,
        authority=authority_url,
        http_client=MockHttpClient()
    )

    # Test case 1: client_id as single scope (should work)
    try:
        result = app._decorate_scope([client_id])
        print(f"✓ Single client_id scope works: {result}")
    except Exception as e:
        print(f"✗ Single client_id scope failed: {e}")

    # Test case 2: client_id mixed with other scopes (should fail currently)
    try:
        result = app._decorate_scope(['openid', 'offline_access', client_id])
        print(f"✓ Mixed scopes with client_id works: {result}")
    except Exception as e:
        print(f"✗ Mixed scopes with client_id failed (expected): {e}")


def test_azure_b2c_logic():
    """Test Azure B2C behavior logic without network calls"""
    print("\nTesting Azure B2C behavior logic...")

    # Test B2C authority detection logic
    b2c_authorities = [
        "https://contoso.b2clogin.com/contoso.onmicrosoft.com/B2C_1_signup_signin",
        "https://fabrikam.b2clogin.cn/fabrikam.onmicrosoft.com/B2C_1_signup_signin",
        "https://custom.b2clogin.de/tenant.onmicrosoft.de/B2C_1_signup_signin"
    ]

    regular_authorities = [
        "https://login.microsoftonline.com/common",
        "https://login.microsoftonline.com/organizations",
        "https://login.microsoftonline.com/tenant-id"
    ]

    class MockHttpClient:
        def get(self, url, **kwargs):
            return type('Response', (), {
                'status_code': 200,
                'text': json.dumps({
                    'authorization_endpoint': f'{url.replace("/.well-known/openid-configuration", "")}/authorize',
                    'token_endpoint': f'{url.replace("/.well-known/openid-configuration", "")}/token'
                })
            })()

    client_id = "test-client-id-b2c"

    print("B2C Authority Detection:")
    for authority_url in b2c_authorities:
        try:
            authority = Authority(authority_url, MockHttpClient())
            print(f"  {authority_url} -> B2C: {authority._is_b2c}")
        except Exception as e:
            print(f"  {authority_url} -> Error: {e}")

    print("Regular Authority Detection:")
    for authority_url in regular_authorities[:2]:  # Just test a couple
        try:
            authority = Authority(authority_url, MockHttpClient())
            print(f"  {authority_url} -> B2C: {authority._is_b2c}")
        except Exception as e:
            print(f"  {authority_url} -> Error: {e}")


def test_current_issue():
    """Demonstrate the current issue with B2C scopes"""
    print("\nDemonstrating current issue...")

    class MockHttpClient:
        def get(self, url, **kwargs):
            return type('Response', (), {
                'status_code': 200,
                'text': json.dumps({
                    'authorization_endpoint': 'https://contoso.b2clogin.com/contoso.onmicrosoft.com/B2C_1_signup_signin/oauth2/v2.0/authorize',
                    'token_endpoint': 'https://contoso.b2clogin.com/contoso.onmicrosoft.com/B2C_1_signup_signin/oauth2/v2.0/token'
                })
            })()

    client_id = "test-client-id-b2c"
    authority_url = "https://contoso.b2clogin.com/contoso.onmicrosoft.com/B2C_1_signup_signin"

    app = PublicClientApplication(
        client_id=client_id,
        authority=authority_url,
        http_client=MockHttpClient()
    )

    print(f"Is B2C authority: {app.authority._is_b2c}")

    # This is what should work for B2C but currently fails
    try:
        result = app._decorate_scope(['openid', 'offline_access', client_id])
        print(f"✓ B2C mixed scopes work: {result}")
    except Exception as e:
        print(f"✗ B2C mixed scopes failed (current issue): {e}")

    # This is what currently works (but doesn't give access_token for B2C)
    try:
        result = app._decorate_scope([client_id])
        print(f"✓ Single client_id scope works: {result}")
    except Exception as e:
        print(f"✗ Single client_id scope failed: {e}")


def test_expected_behavior():
    """Show what the expected behavior should be"""
    print("\nExpected behavior demonstration:")
    print("- Regular Azure AD: client_id must be alone as scope")
    print("- Azure B2C: client_id can be combined with other scopes like 'openid', 'offline_access'")
    print("- This allows Azure B2C to return access_tokens for the application")


if __name__ == "__main__":
    test_regular_azure_ad()
    test_azure_b2c_logic()
    test_current_issue()
    test_expected_behavior()

