#!/usr/bin/env python3
"""
Script to test the fix for Azure B2C client_id in scopes issue.
"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'msal'))

from msal.application import ClientApplication
import json


def test_non_b2c_behavior():
    """Test that non-B2C behavior is preserved"""
    print("Testing NON-B2C behavior (should be unchanged)...")

    client_id = "test-client-id"

    # Create a minimal ClientApplication instance for testing _decorate_scope
    class TestApp(ClientApplication):
        def __init__(self, client_id):
            self.client_id = client_id
            self._exclude_scopes = set()
            # Mock authority with B2C detection
            class MockAuthority:
                _is_b2c = False
            self.authority = MockAuthority()

    app = TestApp(client_id)

    # Test case 1: client_id as single scope (should work)
    try:
        result = app._decorate_scope([client_id])
        print(f"✓ Single client_id scope works: {result}")
    except Exception as e:
        print(f"✗ Single client_id scope failed: {e}")

    # Test case 2: reserved scopes provided by user (should fail for non-B2C)
    try:
        result = app._decorate_scope(['openid', 'offline_access'])
        print(f"✗ Reserved scopes should fail for non-B2C: {result}")
    except Exception as e:
        print(f"✓ Reserved scopes correctly rejected for non-B2C: {e}")

    # Test case 3: client_id mixed with other scopes (should fail for non-B2C)
    try:
        result = app._decorate_scope(['custom_scope', client_id])
        print(f"✗ Mixed scopes should fail for non-B2C: {result}")
    except Exception as e:
        print(f"✓ Mixed scopes correctly rejected for non-B2C: {e}")


def test_b2c_behavior():
    """Test that B2C behavior now works"""
    print("\nTesting B2C behavior (should be fixed)...")

    client_id = "test-client-id-b2c"

    # Create a minimal ClientApplication instance for testing _decorate_scope
    class TestApp(ClientApplication):
        def __init__(self, client_id):
            self.client_id = client_id
            self._exclude_scopes = set()
            # Mock authority with B2C detection
            class MockAuthority:
                _is_b2c = True
            self.authority = MockAuthority()

    app = TestApp(client_id)

    # Test case 1: client_id as single scope (should still work)
    try:
        result = app._decorate_scope([client_id])
        print(f"✓ Single client_id scope works: {result}")
    except Exception as e:
        print(f"✗ Single client_id scope failed: {e}")

    # Test case 2: Azure B2C required combination (should now work!)
    try:
        result = app._decorate_scope(['openid', 'offline_access', client_id])
        print(f"✓ B2C mixed scopes work: {result}")
        # Should include all scopes plus the standard reserved ones
        expected_scopes = {'openid', 'offline_access', client_id, 'profile'}
        actual_scopes = set(result)
        if expected_scopes <= actual_scopes:
            print(f"  ✓ Contains all expected scopes")
        else:
            print(f"  ✗ Missing expected scopes. Expected superset of {expected_scopes}, got {actual_scopes}")
    except Exception as e:
        print(f"✗ B2C mixed scopes failed: {e}")

    # Test case 3: Other reserved scopes should also work for B2C
    try:
        result = app._decorate_scope(['openid', client_id])
        print(f"✓ B2C openid + client_id works: {result}")
    except Exception as e:
        print(f"✗ B2C openid + client_id failed: {e}")


def test_edge_cases():
    """Test edge cases"""
    print("\nTesting edge cases...")

    client_id = "test-client-id-b2c"

    class TestApp(ClientApplication):
        def __init__(self, client_id, is_b2c=True):
            self.client_id = client_id
            self._exclude_scopes = set()
            class MockAuthority:
                _is_b2c = is_b2c
            self.authority = MockAuthority()

    # Test normal scopes without client_id (should work for both)
    for is_b2c in [True, False]:
        app = TestApp(client_id, is_b2c)
        try:
            result = app._decorate_scope(['custom_scope1', 'custom_scope2'])
            print(f"✓ Normal scopes work for {'B2C' if is_b2c else 'non-B2C'}: {result}")
        except Exception as e:
            print(f"✗ Normal scopes failed for {'B2C' if is_b2c else 'non-B2C'}: {e}")


if __name__ == "__main__":
    test_non_b2c_behavior()
    test_b2c_behavior()
    test_edge_cases()
